function exec(cmd, opts = {}) {
  try {
    return execSync(cmd, {
      timeout: opts.timeout || 120000,
      encoding: 'utf8',
      maxBuffer: 5 * 1024 * 1024,
      cwd: ROOT,
      windowsHide: true,
      ...opts
    }).trim();
  } catch (e) { return opts.fallback || `[ERROR: ${e.message?.slice(0, 80)}]`; }
}

